import{t as o}from"./chunk-DUM3lJUO.js";var t={capabilityId:`debate.inquiry-portfolio`,version:`1.0`,recordSummary:`All eight civilization concepts are needed for FF.G6.SS.10.`,hearingGateId:`h-c`,introduction:`You are an advocate in a classroom hearing about ancient Babylon. Read the sources, build a case, and decide for yourself. The hearing is our learning format; it is not a reenactment of a known trial.`,artworkCaption:`Imagined Old Babylonian courtyard · about 1750 BCE · present-day Iraq. AI-created educational illustration; not historical evidence.`,targets:[{id:`sources`,standardId:`FF.G6.SS.01`,label:`Gather sources`,prompt:`Identify a primary text, an artifact record, and a secondary explanation you used. Give each source’s origin, citation, and relevance. What source would help fill a remaining gap?`,sourceIds:[`law-55`,`writing`,`ziggurat`]},{id:`analysis`,standardId:`FF.G6.SS.02`,label:`Examine sources`,prompt:`Paraphrase a law. Separate a fact in the text, your opinion, and an inference. Compare its purpose and viewpoint with a museum explanation. Explain a possible bias and a limit on what the sources prove.`,sourceIds:[`law-48`,`royal-monument`]},{id:`argument`,standardId:`FF.G6.SS.04`,label:`Argue with evidence`,prompt:`State a claim with citations and reasoning. Fairly answer an opposing view. Propose a law change and predict effects on two groups. Describe one respectful exchange from the hearing. Link your brief, revision, and personal defense.`,sourceIds:[`law-48`,`law-55`,`law-fees`]},{id:`monarchy`,standardId:`FF.G6.SS.10`,label:`Monarchy`,prompt:`What is monarchy? Explain how Hammurabi’s authority illustrates it. Cite a source and distinguish a royal claim from proof.`,sourceIds:[`royal-monument`]},{id:`empire`,standardId:`FF.G6.SS.10`,label:`Empire`,prompt:`How does an empire differ from one city? Explain why governing several cities could make laws useful to Hammurabi.`,sourceIds:[`river-cities`,`royal-monument`]},{id:`hierarchy`,standardId:`FF.G6.SS.10`,label:`Social hierarchy`,prompt:`Explain social hierarchy using a law about medical fees. Who is treated differently? What does this reveal, and what can it not prove?`,sourceIds:[`law-fees`]},{id:`polytheism`,standardId:`FF.G6.SS.10`,label:`Polytheism`,prompt:`Explain polytheism and how religious beliefs appear in the ruler’s claims about authority. Cite the prologue source.`,sourceIds:[`gods-and-king`]},{id:`cuneiform`,standardId:`FF.G6.SS.10`,label:`Cuneiform`,prompt:`Explain why cuneiform is a writing system rather than a language. How could writing help preserve laws and other knowledge? Cite an object or text.`,sourceIds:[`writing`,`royal-monument`]},{id:`architecture`,standardId:`FF.G6.SS.10`,label:`Monumental architecture`,prompt:`Use the ziggurat at Ur to explain monumental architecture, organized labor, and religion. Explain why this is regional context rather than an image of Babylon’s courtroom.`,sourceIds:[`ziggurat`]},{id:`literature`,standardId:`FF.G6.SS.10`,label:`Epic literature`,prompt:`Explain how the Gilgamesh passage shows a concern of epic literature. How is a heroic story useful to a historian, and different from a law or eyewitness report?`,sourceIds:[`epic`]},{id:`code`,standardId:`FF.G6.SS.10`,label:`Code of Hammurabi`,prompt:`Explain the Code as a royal collection of judgments. Apply one cited law to a new example, then evaluate order and fairness separately. Do written expectations prove actual enforcement?`,sourceIds:[`royal-monument`,`law-55`,`law-fees`]}],gates:[{id:`h-a`,label:`H-A · Ready to interpret laws`,afterLesson:2,criteria:`Independently explain royal authority and hierarchy with a source before dependent case interpretation.`},{id:`h-b`,label:`H-B · Ready to rehearse`,afterLesson:4,criteria:`Explain a cited law in context, link it to a claim, and fairly describe a defensible opposing view.`},{id:`h-c`,label:`H-C · Ready for the final hearing`,afterLesson:7,criteria:`Independently apply a law in context and review the individual portfolio. Open standard components remain open.`}],lessons:[{number:1,title:`Meet Babylon`,task:`Start with the rivers, the cities, and the king. Explain who had power before deciding whether a law was fair.`,sourceIds:[`river-cities`,`royal-monument`,`law-fees`],targetIds:[`sources`,`analysis`,`monarchy`,`empire`,`hierarchy`],fields:[{id:`context`,label:`My explanation`,prompt:`How did farms, trade, and cities connect? Explain monarchy, empire, and hierarchy using a source.`},{id:`source`,label:`My source note`,prompt:`Name the source, its origin, whether it is primary or secondary, and one question it leaves you with.`}],check:`Explain the difference between a city and an empire. Use one source to show how a king or social status could affect people.`,retry:`Imagine Babylon adds another city to its rule. Explain what changes about its government and whose viewpoint a royal monument presents.`,help:`Begin with one link: river → irrigation → farms → cities. Monarchy means a king or queen rules; hierarchy means people hold different social positions. Now find a source example.`,sideQuest:`Compare what a king’s monument and a farmer’s account could reveal. What perspective is missing from our packet?`,teacher:`Model source identification; check agriculture, trade, and cities. Teach monarchy, empire, and hierarchy before law interpretation.`,tutor:`Ask for the learner’s own explanation, then ask which source supports it. Flag confusion between a city, an empire, and a modern nation.`,workload:`About 45–60 minutes: 10-minute model, 20–30 minutes of source work, one short personal check. Two notes; roughly 80–120 words total.`},{number:2,title:`Plan the case together`,task:`Define order and fairness. Choose an assigned case and a job for everyone. Each person still keeps their own explanation.`,sourceIds:[`gods-and-king`,`ziggurat`,`royal-monument`,`law-fees`],targetIds:[`sources`,`argument`,`monarchy`,`hierarchy`,`polytheism`,`architecture`],fields:[{id:`team`,label:`Our case plan · my copy`,prompt:`State the question, what order and fairness mean, each member’s job, and two sources to explore. Share this plan with your group.`},{id:`context`,label:`My context note`,prompt:`Explain polytheism and monumental architecture. Connect a source to royal authority or hierarchy.`}],check:`H-A: Explain royal authority and social hierarchy in your own words. Use a source for each, and distinguish the ruler’s claim from your judgment.`,retry:`H-A recheck: A monument praises the king, while a law sets different fees by status. Explain what each tells you about authority and hierarchy.`,help:`Take one source at a time. Use “This source shows… because…”. Your teacher can model another example before you try a fresh check.`,sideQuest:`Find a plausible reason someone might value order yet question fairness. What further evidence would test that idea?`,teacher:`Check every member, including clerks and judges. Review H-A before dependent law interpretation; keep source reading and other team roles available.`,tutor:`Ask each student privately about their contribution and source, not only the spokesperson. Suggest a source reread; teacher decides H-A.`,workload:`About 45–60 minutes: one group outline, one personal context note, one H-A check per learner.`},{number:3,title:`Read the evidence`,task:`Read a law as a historical source. Explore how writing preserved laws and how epic literature preserved stories.`,requiresGate:`h-a`,sourceIds:[`writing`,`epic`,`law-48`,`law-55`,`law-fees`],targetIds:[`sources`,`analysis`,`cuneiform`,`literature`,`code`],fields:[{id:`annotation`,label:`My law analysis`,prompt:`Cite and paraphrase one law. Identify a fact, an opinion, an inference, the source’s purpose, and a limit on what it proves.`},{id:`context`,label:`Writing and stories`,prompt:`Explain cuneiform and epic literature. Use the brick and Gilgamesh sources; distinguish their dates, purposes, and places.`}],check:`Compare a royal legal judgment with the Gilgamesh passage. What can each tell a historian, and what can neither establish on its own?`,retry:`Explain why an inscribed brick and a translated law are different kinds of evidence. Give one justified inference and one claim you cannot support.`,help:`Read the adapted excerpt aloud or in smaller pieces. Separate “the text says” from “I infer”. An epic is a story; a law states a judgment.`,sideQuest:`Compare the adaptation with the linked translation. Identify one wording choice that might affect an interpretation.`,teacher:`Teach cuneiform, epic literature, and the Code. Verify all eight S10 concepts have now been introduced; model purpose and bias analysis.`,tutor:`Ask the learner to paraphrase before giving a hint. Probe source purpose and unsupported inferences; use a fresh no-hint question for the check.`,workload:`About 45–60 minutes: two short source analyses plus one independent comparison. Revisit the eight context entries over the project.`},{number:4,title:`Build the first argument`,task:`Combine your team’s ideas, then build your own claim, evidence, and explanation. A strong case takes the other side seriously.`,requiresGate:`h-a`,sourceIds:[`law-48`,`law-55`,`law-fees`,`royal-monument`],targetIds:[`analysis`,`argument`,`code`],fields:[{id:`claim`,label:`My claim`,prompt:`What does your assigned case argue about order or fairness?`},{id:`evidence`,label:`My evidence and why`,prompt:`Cite two sources. Explain how each supports the claim in its historical context.`},{id:`opponent`,label:`Another interpretation`,prompt:`What is the strongest fair interpretation the other side could offer? Respond to its evidence.`}],check:`H-B: Apply a cited law to a case, explain how it supports your claim, and give a defensible opposing interpretation. Explain the difference between a law’s aim and proof of its effect.`,retry:`H-B recheck: A neighbor loses grain after careless irrigation. Use law 55 to argue a case, then show how someone could question your conclusion about fairness.`,help:`Try “My claim… My source… This matters because…”. The teacher can model a different law before your fresh independent check.`,sideQuest:`Find a counterexample to your claim. Narrow the claim so that it remains defensible.`,teacher:`Check each learner’s brief and H-B reasoning before formal rehearsal. Judge evidence rather than agreement with a preferred verdict.`,tutor:`Ask each member to defend one source-to-claim link and acknowledge an opposing view. Recommend revision when the link is missing; teacher decides readiness.`,workload:`About 45–60 minutes: a first individual brief, roughly 250–400 words across the three fields, plus one H-B check. Length is a guide, not a gate.`},{number:5,title:`Revise and predict`,task:`Improve a weak part of your argument. Propose a change to a law and think through who might be helped or harmed.`,requiresGate:`h-a`,sourceIds:[`law-48`,`law-55`,`law-fees`],targetIds:[`analysis`,`argument`,`hierarchy`,`code`],fields:[{id:`revision`,label:`My revision`,prompt:`Keep the original claim in Lesson 4. Write a stronger version here and explain the evidence or feedback that changed it.`},{id:`prediction`,label:`My proposed law change`,prompt:`Label your change hypothetical. Predict an effect for two groups and one unintended consequence. Explain your cause-and-effect reasoning.`}],check:`Explain a correction to your claim. Defend a hypothetical law change with evidence and predict different consequences for two groups.`,retry:`A proposed law gives the same medical fee for every patient. Predict a benefit and a possible problem, using the source while keeping your prediction separate from historical fact.`,help:`Choose only one claim to revise. Use “Before… Now… My evidence…”. For a prediction use “If… then… because…”. Retry H-B in Lesson 4 after reteaching.`,sideQuest:`Explain why a well-intended law could have an unwanted consequence. Propose evidence that could test your prediction.`,teacher:`Reteach weak reasoning; preserve before-and-after work. Recheck H-B with a fresh prompt if needed.`,tutor:`Ask what changed and why. Distinguish a prediction from a fact; give scaffolding in practice, then remove answer-generating hints for the check.`,workload:`About 45–60 minutes: one revised passage, one hypothetical law change, one personal check. Around 120–180 new words.`},{number:6,title:`Practice the hearing`,task:`Take turns making a case, listening, and responding. Use an actual classmate’s words; every member must explain their own thinking.`,requiresGate:`h-b`,sourceIds:[`law-48`,`law-55`,`law-fees`],targetIds:[`analysis`,`argument`,`code`],fields:[{id:`listening`,label:`What I heard`,prompt:`Name your partner and fairly paraphrase a real claim they made. Which source did they use?`},{id:`response`,label:`My response and improvement`,prompt:`Answer that claim with evidence. Explain one change you made after the practice. Keep a transcript or recording reference.`}],check:`Defend one change prompted by the rehearsal. Respond to an opposing claim using a cited source and acknowledge a limitation.`,retry:`Choose a different real opposing claim from the practice. Explain its evidence fairly before giving your evidence-based response.`,help:`Listen once for the main claim and again for the evidence. Rehearse one sentence at a time. If H-B needs work, revise Lesson 4 and request a fresh review.`,sideQuest:`Identify a point both cases can accept and one disagreement the sources cannot settle.`,teacher:`Observe respectful discourse and question every student. Recheck critical gaps; do not substitute a team performance for personal evidence.`,tutor:`Ask a private follow-up about each learner’s response and revision. Keep class moderator questions separate from private practice notes.`,workload:`About 45–60 minutes: one practice hearing, one question/response per learner, and one revision note. Use supported speaking or transcript routes as needed.`},{number:7,title:`Defend your thinking`,task:`Use a fresh case to show what you can do independently. Review your source notes, brief, revision, and all eight civilization concepts.`,requiresGate:`h-b`,sourceIds:[`law-48`,`law-55`,`law-fees`,`royal-monument`],targetIds:[`sources`,`analysis`,`argument`,`monarchy`,`empire`,`hierarchy`,`polytheism`,`cuneiform`,`architecture`,`literature`,`code`],fields:[{id:`portfolio`,label:`My evidence for the final`,prompt:`Identify your source notes, brief, revision, prediction, and practice response by lesson. In My learning record, revisit each open concept separately.`}],check:`H-C: A farmer’s crop fails because rain does not arrive; another farmer carelessly floods a neighbor. Compare the relevant laws. Defend a conclusion about order and fairness in context, and identify a limitation in your evidence.`,retry:`H-C recheck: A ruler claims that written laws make society fair. Use two different laws and a context source to evaluate that claim. What further evidence would you need?`,help:`Review sources and earlier feedback before starting the check. Practice with the teacher, then answer a fresh case independently. Open sources remain available.`,sideQuest:`Find a new question your sources raise about government or justice. Explain what evidence would answer it.`,teacher:`Review H-C and the individual portfolio. Check every remaining S10 component separately; final readiness does not mean all standards are complete.`,tutor:`Ask a new transfer question, log the independent response, and flag unsupported reasoning. Teacher confirms readiness and component evidence.`,workload:`About 45–60 minutes: one short transfer defense and a portfolio review. Check remaining concepts individually; allow focused reassessment rather than repeating everything.`},{number:8,title:`Hammurabi on trial`,task:`Present the final hearing. Then give your own verdict: order, fairness, both, or neither. Your evidence and reasoning matter more than winning.`,requiresGate:`h-c`,sourceIds:[`law-48`,`law-55`,`law-fees`,`royal-monument`],targetIds:[`sources`,`analysis`,`argument`,`code`],fields:[{id:`final`,label:`My final brief`,prompt:`Bring your revised claim, citations, opposing view, rebuttal, and proposed law change into one final brief. Keep your earlier drafts in the previous lessons.`},{id:`verdict`,label:`My verdict and reflection`,prompt:`Order, fairness, both, or neither? Explain why, what changed your thinking, and your own contribution. Your verdict can differ from your assigned team case.`}],check:`Defend one specific claim from your final work with a source. Answer a follow-up about a limitation and explain your own contribution to the hearing.`,retry:`Choose another source from your final brief. Explain what it proves, what it does not prove, and how it affects your personal verdict.`,help:`Use your brief as speaking notes. Your teacher can arrange audio, a supported live contribution, or a transcript. Revisit only the target that still needs evidence.`,sideQuest:`Compare a principle from your verdict with a different historical legal system using a teacher-approved source.`,teacher:`Run the hearing and personal defenses. Review all evidence before confirming each standard; S10 needs all eight concepts, and votes never award mastery.`,tutor:`Ask every learner a defense question tied to their own work. Summarize evidence gaps for teacher review; do not infer mastery from team success.`,workload:`About 45–60 minutes including an 8–12-minute team hearing and individual defenses. Final brief roughly 250–400 words; accommodations preserve the reasoning targets.`}]};var r={schemaVersion:`1.0`,lessons:o([{title:`Separate order from fairness`,claim:`Which opening makes a supportable claim about the Code?`,strongest:0,sourceIds:[`river-cities`,`royal-monument`,`law-48`,`law-fees`],choices:[{text:`Law 48 describes crop-failure relief. Examine other laws before claiming fairness for every group.`,feedback:`A specific law supports a limited claim. The city and royal sources add monarchy and empire context; medical fees raise hierarchy questions.`},{text:`A written code proves everyone was treated equally.`,feedback:`A written rule does not prove equal treatment or enforcement. Compare the groups in the medical-fee source.`}]},{title:`Compare purpose and genre`,claim:`How should a speaker use royal claims, written law and an epic?`,strongest:1,sourceIds:[`gods-and-king`,`writing`,`epic`,`royal-monument`],choices:[{text:`Treat royal promises and an epic as records of everyday enforcement.`,feedback:`Purpose and genre matter. Neither a royal claim nor literature establishes how every case was handled.`},{text:`Compare beliefs and authority, and distinguish intended rules from proof of practice.`,feedback:`Connect polytheism, kingship, cuneiform and literature without confusing their evidence. Cuneiform is a writing system, not a language.`}]},{title:`Trace a claim and its consequences`,claim:`Your opponent says canal rules could protect farmers. Which rebuttal is strongest?`,strongest:0,sourceIds:[`law-55`,`law-fees`,`ziggurat`],choices:[{text:`Accept that rules could protect neighbors, then examine who bears the cost and how status affects treatment.`,feedback:`A fair concession leaves a question to test. Compare law 55 with medical fees. Use the ziggurat source for architecture, not proof of enforcement.`},{text:`Monumental buildings prove the canal rule worked fairly.`,feedback:`An architectural source cannot establish fair enforcement of a law. Match evidence to the claim.`}]},{title:`Weigh order, fairness and limits`,claim:`Which closing gives a judge a basis for a verdict?`,strongest:1,sourceIds:[`law-48`,`law-55`,`law-fees`,`river-cities`,`ziggurat`,`epic`],choices:[{text:`The Code was old and famous, so it must have been fair.`,feedback:`Age and fame do not establish fairness. Compare specific protections and unequal treatment.`},{text:`Weigh protections against status differences, answer the opposing interpretation and state the limits of the sources.`,feedback:`Distinguish order from fairness. Your context defense must also explain monarchy, empire, hierarchy, polytheism, writing, architecture, literature and law.`}]}],[`Begin context evidence: monarchy, empire and hierarchy.`,`Explain how one law could create order and question fairness.`,`Explain polytheism, cuneiform and literature in your context defense.`,`Distinguish intended protection from evidence of practice.`,`Propose a hypothetical law change and effects on two groups; examine architecture separately.`,`Answer a competing interpretation using a cited law.`,`Compare unavoidable crop failure with negligent canal damage; revisit all eight concepts.`,`Complete all eight civilization concepts in your independent context defense.`]),examples:[{name:`Maya · example`,side:`case-for`,points:[`Specific rules could provide protection.`],speech:`Law 48 describes relief when a crop fails. That is evidence for a particular protection. I argue the Code could help create order, but one law cannot tell us whether all groups were treated fairly.`,evidenceIds:[`law-48`]},{name:`Noah · example`,side:`case-against`,points:[`Order and equal treatment are different tests.`],speech:`The medical-fee source distinguishes people by status. That gives us a reason to question equal treatment. A rule can organize society while preserving social hierarchy.`,evidenceIds:[`law-fees`]},{name:`Elena · example`,side:`case-for`,points:[`Canal responsibilities could protect neighbors.`],speech:`Law 55 connects canal responsibility to damage suffered by neighbors. This could support cooperation around irrigation. The written rule does not prove how every dispute was settled.`,evidenceIds:[`law-55`]},{name:`Sam · example`,side:`case-against`,points:[`Royal promises need critical reading.`],speech:`The royal monument presents the ruler’s authority and purpose. It is useful evidence about kingship, but a royal promise is not proof of fair outcomes. Compare it with the laws themselves.`,evidenceIds:[`royal-monument`,`law-fees`]}]};var i=[{id:`opening-advocate`,label:`Opening advocate`,roundTypes:[`opening`]},{id:`evidence-advocate`,label:`Evidence advocate`,roundTypes:[`response`]},{id:`rebuttal-advocate`,label:`Rebuttal advocate`,roundTypes:[`rebuttal`]},{id:`closing-advocate`,label:`Closing advocate`,roundTypes:[`closing`]}];var e=`https://avalon.law.yale.edu/ancient/hamcode.asp`;var d={schemaVersion:`2.0`,template:{id:`debate-studio`,version:`2.0`},projectId:`hammurabi-on-trial`,projectVersion:`2.0.0`,exchange:r,sessionId:`babylon-hearing`,title:`Hammurabi on Trial`,subtitle:`Order. Fairness. Your verdict.`,historicalSetting:`Babylon · Mesopotamia · about 1750 BCE`,sessionDateLabel:`Grade 6 · Social Studies`,centralQuestion:`Did Hammurabi’s Code create order, fairness, both, or neither?`,chamberImageUrl:`/debate-studio/babylon-hearing-v1.png`,chamberImageAlt:`An imagined Old Babylonian courtyard with earthen brick walls, reed shade, clay tablets, and facing benches. Educational illustration, not a documented ancient courtroom.`,presentation:{assembly:`Hearing`,seal:`LAW`,speaker:`Student advocate`},inquiry:t,factions:[{id:`case-for`,name:`The case for the Code`,shortName:`Case for`,railLabel:`Case for`,position:`Test how written judgments could settle disputes and protect people.`,accent:`#d4ad6e`,emblem:`+`,roles:i},{id:`case-against`,name:`The case against the Code`,shortName:`Case against`,railLabel:`Case against`,position:`Test unequal treatment and the limits of royal claims about justice.`,accent:`#79c4c2`,emblem:`?`,roles:i}],rounds:[{id:`opening`,type:`opening`,label:`Opening cases`,mode:`parallel`,moderatorBeforeTurn:!1,timeLimitSeconds:90,minimumSeconds:0,minimumEvidence:2,allowNewEvidence:!0,preparationPrompts:[`State your assigned case.`,`Cite two sources and explain them in context.`,`Distinguish evidence for order from evidence for fairness.`]},{id:`response`,type:`response`,label:`Evidence exchange`,mode:`alternating`,speakerOrder:[`case-for`,`case-against`],moderatorBeforeTurn:!0,timeLimitSeconds:90,minimumSeconds:0,minimumEvidence:1,allowNewEvidence:!0,preparationPrompts:[`Listen to the actual opposing contribution.`,`Name the claim you are answering.`,`Explain why a cited law supports your response.`]},{id:`rebuttal`,type:`rebuttal`,label:`Questions and rebuttals`,mode:`alternating`,speakerOrder:[`case-for`,`case-against`],moderatorBeforeTurn:!0,timeLimitSeconds:90,minimumSeconds:0,minimumEvidence:1,allowNewEvidence:!0,preparationPrompts:[`Describe the strongest opposing interpretation fairly.`,`Answer it with evidence.`,`Propose a law change and predict a consequence for two groups.`]},{id:`closing`,type:`closing`,label:`Closing cases`,mode:`parallel`,moderatorBeforeTurn:!1,timeLimitSeconds:90,minimumSeconds:0,minimumEvidence:2,allowNewEvidence:!1,preparationPrompts:[`Explain what the evidence establishes and what remains uncertain.`,`Respond to a limitation.`,`Your personal verdict may differ from your assigned case.`]}],moderator:{title:`A question for the hearing`,displayName:`Hearing moderator`,initials:`HM`,mode:`teacher-written`,requiredConcepts:[`law and authority`,`social hierarchy`,`order and fairness`,`source perspective`,`unintended consequences`],promptPriorities:[`unanswered claim`,`source limitation`,`individual explanation`,`different consequences for different groups`]},evidence:[{id:`river-cities`,title:`Rivers, farms, and cities`,dateLabel:`Mesopotamian background`,sourceType:`Secondary learning summary`,excerpt:`Southern Mesopotamian communities used irrigation to bring river water to fields. Farming supported cities, specialized work, and exchange. Shared water systems also created responsibilities between neighbors.`,context:`Babylon was a city on the Euphrates in present-day Iraq. A city is not the same thing as an empire: an empire brings multiple territories and peoples under one ruler.`,citation:`Learning summary; compare the irrigation dispute in Hammurabi, §55, and the Met’s Ur: The Ziggurat.`,sourceUrl:`https://www.metmuseum.org/essays/ur-the-ziggurat`,perspective:`Modern overview; a starting point to verify with sources`},{id:`royal-monument`,title:`A king’s statement in stone`,dateLabel:`About 1750 BCE`,sourceType:`Artifact described by a museum`,excerpt:`Hammurabi, king of Babylon, had a collection of judgments inscribed on a tall dark stone monument. The collection deals with family, property, work, and trade. A royal monument presents the ruler’s view of justice.`,context:`Monarchy means rule by a king or queen. Hammurabi extended Babylon’s rule over other cities. A ruler’s claim to be just does not prove that every person experienced justice.`,citation:`Louvre, The Code of Hammurabi; object Sb 8. Classroom paraphrase of the museum explanation, not words spoken by Hammurabi.`,sourceUrl:`https://www.louvre.fr/en/the-code-of-hammurabi`,perspective:`Royal self-presentation interpreted by a modern museum`},{id:`law-48`,title:`Law 48 · A failed harvest`,dateLabel:`About 1750 BCE`,sourceType:`Primary law, adapted from translation`,excerpt:`When a storm, failed harvest, or lack of water ruins a debtor’s crop, the law allows relief from the grain payment for that year.`,context:`Compare the farmer’s needs with the lender’s expectations. This is a classroom paraphrase, not an exact quotation or a claim that all debts were erased.`,citation:`Hammurabi §48; L. W. King translation hosted by Yale’s Avalon Project. Adapted for classroom reading.`,sourceUrl:e,perspective:`Royal legal judgment`},{id:`law-55`,title:`Law 55 · Water damages a neighbor’s field`,dateLabel:`About 1750 BCE`,sourceType:`Primary law, adapted from translation`,excerpt:`Someone who carelessly floods a neighbor’s field while irrigating must replace the lost crop with grain.`,context:`Use this law to test responsibility and compensation. It tells us an expected judgment, not how often judges enforced it.`,citation:`Hammurabi §55; L. W. King translation, Yale Avalon Project. Classroom paraphrase.`,sourceUrl:e,perspective:`Royal legal judgment`},{id:`law-fees`,title:`Laws 215–217 · Different medical fees`,dateLabel:`About 1750 BCE`,sourceType:`Primary laws, adapted from translation`,excerpt:`For a successful operation described in these laws, the fee varies with the patient’s status: ten, five, or two shekels. For an enslaved patient, the owner pays.`,context:`Social hierarchy means unequal positions in society. Translations use different labels for status groups; do not equate them directly with modern income groups. Compare who pays and whose interests are represented.`,citation:`Hammurabi §§215–217; L. W. King translation, Yale Avalon Project. Classroom paraphrase; historical status terms need teacher explanation.`,sourceUrl:e,perspective:`A society with legal status differences and enslavement`},{id:`gods-and-king`,title:`Religion and royal authority`,dateLabel:`About 1750 BCE`,sourceType:`Primary prologue, summarized`,excerpt:`The prologue names several gods and presents Hammurabi’s authority as connected to them. Polytheism is belief in many gods.`,context:`Identify this as the ruler’s claim about his authority. Religious language can show beliefs and political purpose without proving that every subject agreed.`,citation:`Hammurabi, prologue; L. W. King translation, Yale Avalon Project. Classroom summary.`,sourceUrl:e,perspective:`Royal and religious authority`},{id:`writing`,title:`Cuneiform · Writing that can travel through time`,dateLabel:`Old Babylonian period`,sourceType:`Artifact record and secondary explanation`,excerpt:`Cuneiform is a writing system made from wedge-shaped signs. Scribes used it for languages including Sumerian and Akkadian. A surviving inscribed brick from Eshnunna is one example of writing on building material.`,context:`The linked brick is from about the 20th century BCE, earlier than Hammurabi. It is not a piece of his law monument. Writing is a system; Akkadian is a language.`,citation:`Metropolitan Museum of Art, Inscribed brick, 41.160.188, Eshnunna, ca. 20th century BCE; classroom explanation.`,sourceUrl:`https://www.metmuseum.org/art/collection/search/323756`,perspective:`Material evidence interpreted by a museum`},{id:`ziggurat`,title:`Monumental architecture · The ziggurat at Ur`,dateLabel:`Built before Hammurabi’s reign`,sourceType:`Secondary museum explanation`,excerpt:`Ziggurats were large stepped structures made from brick. Building and maintaining them required organized materials and labor, and they were associated with religious life.`,context:`Ur is a different Mesopotamian city from Babylon. Its ziggurat provides regional context, not a photograph of Hammurabi’s hearing room. Large buildings can express religious and political importance.`,citation:`Metropolitan Museum of Art, Ur: The Ziggurat. Classroom paraphrase.`,sourceUrl:`https://www.metmuseum.org/essays/ur-the-ziggurat`,perspective:`Modern interpretation of architecture`},{id:`epic`,title:`Epic literature · Gilgamesh and Huwawa`,dateLabel:`Sumerian literary tradition`,sourceType:`Primary literary text in translation`,excerpt:`“I want to set off into the mountains, to establish my renown there.”`,context:`In this story Gilgamesh seeks lasting fame and speaks to the god Utu. Epic literature tells stories of heroic deeds and human concerns. It is evidence about literature and values, not an eyewitness report of Hammurabi’s life.`,citation:`Gilgamesh and Huwawa, version A, lines 21–33. ETCSL 1.8.1.5, University of Oxford translation. Brief exact excerpt; Gilgamesh is rendered Gilgamec in that edition.`,sourceUrl:`https://etcsl.orinst.ox.ac.uk/section1/tr1815.htm`,perspective:`Literary story, not a legal record`}],opinionOptions:[{id:`order`,label:`Order`},{id:`fairness`,label:`Fairness`},{id:`both`,label:`Both`},{id:`neither`,label:`Neither`}],voteCategories:[{id:`evidence`,label:`Evidence reflection`,prompt:`Which case best connected a claim to its sources? This vote is not a grade.`,optionSource:`factions`}],viewer:{studentId:`preview-learner`,studentDisplayName:`Learner`,classLabel:`Grade 6 Social Studies`,classId:`babylon-pilot`,teacherDisplayName:`Teacher`,factionId:`case-for`,roleLabel:`Student advocate`,mode:`preview`,allowTeacherPreview:!0},seedTurns:[],seedModeratorPrompts:[]};export{d as hammurabiOnTrialConfig};